import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")
    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Deduplicate events by seq (keep first occurrence)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first").reset_index(drop=True)

    # Step 2: Apply replay guard – filter out events where seq <= last_seq for existing orders
    target_dict = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            target_dict[row["order_id"]] = row["last_seq"]

    def passes_replay_guard(row):
        order_id = row["order_id"]
        seq = row["seq"]
        if order_id in target_dict:
            return seq > target_dict[order_id]
        return True

    cdc_events["passes_guard"] = cdc_events.apply(passes_replay_guard, axis=1)
    cdc_events = cdc_events[cdc_events["passes_guard"]].drop(columns=["passes_guard"]).reset_index(drop=True)

    # Step 3: Sort events by seq to apply in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Initialize state: convert target_state to dict for fast lookup
    state = {}
    for _, row in target_state.iterrows():
        state[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders have been touched and their last operation
    last_op = {}  # order_id -> (op, seq)

    # Step 4: Apply events in seq order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        if op == "I" or op == "U":
            if order_id in state:
                # Update existing row
                state[order_id]["status"] = status
                # For 'U': NULL amount leaves existing amount unchanged
                if op == "U" and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    # 'I' or 'U' with non-NULL amount: set it
                    state[order_id]["amount"] = amount
                state[order_id]["last_seq"] = seq
            else:
                # Create new row
                state[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            last_op[order_id] = (op, seq)
        elif op == "D":
            if order_id in state:
                del state[order_id]
            last_op[order_id] = (op, seq)

    # Step 5: Build new_state
    new_state_rows = []
    for order_id, record in state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": record["status"],
            "amount": record["amount"],
            "last_seq": record["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.sort_values("order_id").reset_index(drop=True)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state["order_id"] = new_state["order_id"].astype("int64")
    new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # Step 6: Build tombstones – orders where last applied event is 'D'
    tombstone_rows = []
    for order_id, (op, seq) in last_op.items():
        if op == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": seq
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.sort_values("order_id").reset_index(drop=True)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones["order_id"] = tombstones["order_id"].astype("int64")
    tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
